import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function SellerProfile() {
    const navigate = useNavigate();
    const fileInputRef = useRef(null);
    const [profileData, setProfileData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        phone: '',
        bio: '',
        profileImage: null
    });
    const [loading, setLoading] = useState(false);
    const [stats, setStats] = useState({
        posts: 0,
        followers: 0,
        following: 0,
        views: 0
    });
    const [editing, setEditing] = useState(false);
    const [previewImage, setPreviewImage] = useState(null); // New state for image preview

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        // Load actual user profile data from localStorage
        const loadUserProfile = () => {
            try {
                const userData = localStorage.getItem('user');
                if (userData) {
                    const user = JSON.parse(userData);
                    setProfileData({
                        firstName: user.firstname || '',
                        lastName: user.lastname || '',
                        email: user.email || '',
                        phone: user.telephone || '',
                        bio: user.bio || '',
                        profileImage: user.image || null
                    });
                    setPreviewImage(user.image || null); // Set initial preview image
                }
            } catch (error) {
                console.error('Error loading user profile:', error);
            }
        };

        loadUserProfile();
        loadSellerStats();
    }, []);

    const loadSellerStats = async () => {
        try {
            const response = await ApiService.get('/studio/seller/dashboard/stats');
            if (response.status === 'SUCCESS') {
                setStats(response.data);
            }
        } catch (error) {
            console.error('Error loading seller stats:', error);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setProfileData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        
        try {
            const userData = {
                firstname: profileData.firstName,
                lastname: profileData.lastName,
                email: profileData.email,
                telephone: profileData.phone,
                bio: profileData.bio
            };

            const response = await ApiService.put('/studio/seller/profile', userData);
            
            if (response.status === 'SUCCESS') {
                // Update localStorage with new data
                const currentUser = JSON.parse(localStorage.getItem('user') || '{}');
                const updatedUser = {
                    ...currentUser,
                    firstname: profileData.firstName,
                    lastname: profileData.lastName,
                    email: profileData.email,
                    telephone: profileData.phone,
                    bio: profileData.bio
                };
                localStorage.setItem('user', JSON.stringify(updatedUser));
                
                toast.success('Profile updated successfully!');
                setEditing(false);
            } else {
                toast.error(response.message || 'Failed to update profile');
            }
        } catch (error) {
            toast.error('Failed to update profile');
            console.error('Error updating profile:', error);
        } finally {
            setLoading(false);
        }
    };

    const triggerFileSelect = () => {
        fileInputRef.current.click();
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            // Create preview URL for the selected image
            const imageUrl = URL.createObjectURL(file);
            setPreviewImage(imageUrl);
            
            // In a real implementation, you would upload the file to the server here
            toast.success('Profile picture updated successfully!');
            
            // Clean up the object URL after some time to prevent memory leaks
            setTimeout(() => {
                URL.revokeObjectURL(imageUrl);
            }, 60000);
        }
    };

    const handlePostsClick = () => {
        // Open seller reels page in a new tab
        window.open('/studio/seller/reels', '_blank');
    };

    return (
        <div className="page-wrapper">
            <div className="content container-fluid pb-0">
                {/* Header */}
                <div className="row mb-3">
                    <div className="col-md-12">
                        <div className="page-header">
                            <div className="row align-items-center">
                                <div className="col">
                                    <h3 className="page-title">Profile</h3>
                                    <ul className="breadcrumb">
                                        <li className="breadcrumb-item"><a href="/studio/seller/dashboard">Dashboard</a></li>
                                        <li className="breadcrumb-item active">Profile</li>
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="row">
                    {/* Left Column - Profile Info */}
                    <div className="col-xl-4 col-md-12">
                        {/* Profile Card */}
                        <div className="card">
                            <div className="card-body">
                                <div className="profile-details">
                                    <div className="d-flex align-items-center mb-3">
                                        {/* Profile Image with Camera Icon */}
                                        <div className="position-relative">
                                            <div 
                                                className="avatar avatar-xxl me-3 cursor-pointer"
                                                onClick={triggerFileSelect}
                                                style={{ position: 'relative' }}
                                            >
                                                {previewImage ? (
                                                    <img 
                                                        src={previewImage} 
                                                        alt="Profile" 
                                                        className="rounded-circle img-fluid"
                                                        style={{ width: '80px', height: '80px', objectFit: 'cover' }}
                                                    />
                                                ) : (
                                                    <div className="bg-light rounded-circle d-flex align-items-center justify-content-center" 
                                                         style={{ width: '80px', height: '80px' }}>
                                                        <i className="ri-user-line ri-2x text-muted"></i>
                                                    </div>
                                                )}
                                                <div className="position-absolute bottom-0 end-0 bg-primary rounded-circle p-1">
                                                    <i className="ri-camera-fill text-white"></i>
                                                </div>
                                            </div>
                                            <input 
                                                type="file" 
                                                ref={fileInputRef}
                                                onChange={handleFileChange}
                                                accept="image/*"
                                                className="d-none"
                                            />
                                        </div>
                                        
                                        <div>
                                            <h5>{profileData.firstName} {profileData.lastName}</h5>
                                            <p className="text-muted mb-0">{profileData.email}</p>
                                        </div>
                                    </div>
                                    
                                    {/* Stats */}
                                    <div className="row text-center mt-4">
                                        <div className="col-3">
                                            <h5 className="mb-1">{stats.posts}</h5>
                                            <p className="text-muted mb-0 fs-13">Posts</p>
                                        </div>
                                        <div className="col-3">
                                            <h5 className="mb-1">{stats.followers}</h5>
                                            <p className="text-muted mb-0 fs-13">Followers</p>
                                        </div>
                                        <div className="col-3">
                                            <h5 className="mb-1">{stats.following}</h5>
                                            <p className="text-muted mb-0 fs-13">Following</p>
                                        </div>
                                        <div className="col-3">
                                            <h5 className="mb-1">{stats.views}</h5>
                                            <p className="text-muted mb-0 fs-13">Views</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Quick Actions Card */}
                        <div className="card">
                            <div className="card-header">
                                <h5 className="card-title mb-0">Quick Actions</h5>
                            </div>
                            <div className="card-body">
                                <button 
                                    className="btn btn-primary w-100"
                                    onClick={() => setEditing(true)}
                                >
                                    <i className="ri-edit-line me-1"></i> Edit Profile
                                </button>
                                
                                <button 
                                    className="btn btn-outline-primary w-100 mt-2"
                                    onClick={handlePostsClick}
                                >
                                    <i className="ri-image-line me-1"></i> My Posts
                                </button>
                            </div>
                        </div>
                    </div>

                    {/* Right Column - Edit Form (only shown when editing) */}
                    {editing && (
                        <div className="col-xl-8 col-md-12">
                            <div className="card">
                                <div className="card-header">
                                    <h5 className="card-title mb-0">Edit Profile</h5>
                                </div>
                                <div className="card-body">
                                    <form onSubmit={handleSubmit}>
                                        <div className="row">
                                            <div className="col-md-6">
                                                <div className="mb-3">
                                                    <label className="form-label">First Name</label>
                                                    <input
                                                        type="text"
                                                        className="form-control"
                                                        name="firstName"
                                                        value={profileData.firstName}
                                                        onChange={handleInputChange}
                                                        required
                                                    />
                                                </div>
                                            </div>
                                            <div className="col-md-6">
                                                <div className="mb-3">
                                                    <label className="form-label">Last Name</label>
                                                    <input
                                                        type="text"
                                                        className="form-control"
                                                        name="lastName"
                                                        value={profileData.lastName}
                                                        onChange={handleInputChange}
                                                        required
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                        
                                        <div className="row">
                                            <div className="col-md-6">
                                                <div className="mb-3">
                                                    <label className="form-label">Email Address</label>
                                                    <input
                                                        type="email"
                                                        className="form-control"
                                                        name="email"
                                                        value={profileData.email}
                                                        onChange={handleInputChange}
                                                        required
                                                    />
                                                </div>
                                            </div>
                                            <div className="col-md-6">
                                                <div className="mb-3">
                                                    <label className="form-label">Phone Number</label>
                                                    <input
                                                        type="tel"
                                                        className="form-control"
                                                        name="phone"
                                                        value={profileData.phone}
                                                        onChange={handleInputChange}
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                        
                                        <div className="mb-3">
                                            <label className="form-label">Bio</label>
                                            <textarea
                                                className="form-control"
                                                rows="4"
                                                name="bio"
                                                value={profileData.bio}
                                                onChange={handleInputChange}
                                                placeholder="Tell us about yourself..."
                                            ></textarea>
                                        </div>
                                        
                                        <div className="d-flex justify-content-end gap-2">
                                            <button 
                                                type="button" 
                                                className="btn btn-secondary"
                                                onClick={() => setEditing(false)}
                                                disabled={loading}
                                            >
                                                Cancel
                                            </button>
                                            <button 
                                                type="submit" 
                                                className="btn btn-primary"
                                                disabled={loading}
                                            >
                                                {loading ? 'Saving...' : 'Save Changes'}
                                            </button>
                                        </div>
                                    </form>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
